 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    frames = []
    frame_cells = set()
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0 = min(r for r, _ in cells)
        r1 = max(r for r, _ in cells)
        c0 = min(c for _, c in cells)
        c1 = max(c for _, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        border = {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                  if r in (r0, r1) or c in (c0, c1)}
        if set(cells) == border:
            frames.append((color, r0, r1, c0, c1))
            frame_cells.update(border)

    # The detached colored pixels are a count-keyed palette for the frames.
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != 0 and (r, c) not in frame_cells)
    out = [[0] * w for _ in range(h)]
    for color, r0, r1, c0, c1 in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = color
        inner_h, inner_w = r1 - r0 - 1, c1 - c0 - 1
        needed = (inner_h * inner_w + 1) // 2
        matches = [marker for marker, n in counts.items() if marker != color and n == needed]
        if len(matches) != 1:
            raise ValueError(f"frame color {color}: expected one marker color with count {needed}, got {matches}")
        marker = matches[0]
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if (r - (r0 + 1) + c - (c0 + 1)) % 2 == 0:
